//============================================================================
//  V60 single-precision FP group (0x5C/0x5F) directed test.  Auto-generated by
//  scratchpad/gen_fp_tb.py; expectations from numpy.float32 (IEEE-754 RNE, the
//  MAME host-float contract).  Seeds S_FP_EXEC and checks the result register.
//============================================================================
`timescale 1ns/1ps
module tb_v60_fp;
reg clk = 0, rst = 1;
always #10 clk = ~clk;
wire c_req, c_we, c_ack; wire [31:0] c_addr, c_wdata, c_rdata; wire [1:0] c_size;
wire m_req, m_we, m_ack; wire [23:1] m_addr; wire [15:0] m_wdata, m_rdata; wire [1:0] m_be;
s32_v60 #(.START_PC(32'h0)) cpu (
    .clk(clk), .ce(1'b1), .rst(rst),
    .if_req(), .if_addr(), .if_data(64'd0), .if_ack(1'b0),
    .bus_req(c_req), .bus_we(c_we), .bus_addr(c_addr), .bus_size(c_size),
    .bus_wdata(c_wdata), .bus_rdata(c_rdata), .bus_ack(c_ack),
    .irq_n(1'b1), .irq_vector(8'h00), .irq_ack(), .nmi_n(1'b1));
s32_v60_bus adapter (
    .clk(clk), .ce(1'b1), .rst(rst),
    .c_req(c_req), .c_we(c_we), .c_addr(c_addr), .c_size(c_size),
    .c_wdata(c_wdata), .c_rdata(c_rdata), .c_ack(c_ack),
    .m_req(m_req), .m_we(m_we), .m_addr(m_addr), .m_wdata(m_wdata),
    .m_be(m_be), .m_rdata(m_rdata), .m_ack(m_ack));
reg [15:0] ram [0:32767]; reg ack_r = 0;
assign m_rdata = ram[m_addr[15:1]]; assign m_ack = ack_r;
always @(posedge clk) begin
    if (rst) ack_r <= 0;
    else begin
        ack_r <= m_req && !ack_r;
        if (m_req && m_we && !ack_r) begin
            if (m_be[0]) ram[m_addr[15:1]][7:0]  <= m_wdata[7:0];
            if (m_be[1]) ram[m_addr[15:1]][15:8] <= m_wdata[15:8];
        end
    end
end
integer wd, errors = 0;
task automatic check(input condition, input [255:0] nm);
    if (condition !== 1'b1) begin errors = errors + 1; $display("  FAIL: %0s", nm); end
endtask
// Seed the FP execute stage: fp_a=op1, fp_b=op2, result -> r5.
task automatic run_fp(input [7:0] op, input [7:0] sub, input [31:0] a, input [31:0] b, input [2:0] mode);
    @(negedge clk);
    rst = 1'b1; repeat(2) @(posedge clk); @(negedge clk);
    cpu.st = cpu.S_FP_EXEC;
    cpu.cur_op = op; cpu.subop = {3'b0, sub[4:0]};
    cpu.fp_a = a; cpu.fp_b = b;
    cpu.op2 = 32'd5; cpu.fp_op2_reg = 1'b1;
    cpu.tkcw = {29'b0, mode};
    cpu.len1 = 0; cpu.len2 = 0;
    cpu.dbus_req = 1'b0; cpu.dbus_we = 1'b0;
    rst = 1'b0;
    wd = 0;
    while ((cpu.st !== cpu.S_NEXT) && (wd < 200)) begin @(posedge clk); #1; wd = wd + 1; end
    check(wd < 200, "fp completes");
endtask
